def find_array(n, s, k):
    # Check if it's possible to form the array
    if k < 0 or k > n * (n - 1) // 2:
        return -1
    if k > s:
        return -1

    # Try to find the lexicographically smallest array
    for i in range(n):
        for j in range(n):
            if i != j:
                diff = abs(i - j)
                if k >= diff:
                    k -= diff
                    s -= diff

    # Check if we have used up all the sum of absolute differences
    if k != 0 or s != 0:
        return -1

    # Construct the array
    result = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j:
                diff = abs(j - i)
                if k >= diff:
                    result[i] += 1
                    k -= diff

    return result

